values ('bbbb0002-0000-4000-8000-000000000009', 'en', null, 'Frontend Development', 'Build interactive web interfaces with modern JavaScript, the DOM, async data, and component-based UI. Topic scope and learning outcomes draw on the ACM Computing Curricula recommendations for software development.', null, 'work', 9, true, 'technology', '{bbbb0002-0000-4000-8000-000000000003}')
