insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0002-0000-4000-8000-000000000009', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Which keyword declares a variable that can never be reassigned?","options":["var","let","const","static"],"answer":2,"explanation":"const binds a name that cannot be reassigned — covered in ''Modern JavaScript''."},{"prompt":"What does `[1, 2, 3].map(n => n * 2)` return?","options":["[1, 2, 3]","[2, 4, 6]","6","undefined"],"answer":1,"explanation":"map returns a new array with each element transformed — see ''Modern JavaScript''."},{"prompt":"Which method attaches a click handler to an element?","options":["element.onClick()","element.addEventListener(''click'', fn)","element.click = fn()","element.bind(''click'')"],"answer":1,"explanation":"addEventListener is the standard way to register handlers — see ''The DOM and events''."},{"prompt":"`fetch()` returns a…","options":["string","Promise","number","DOM node"],"answer":1,"explanation":"fetch returns a Promise that resolves to a Response — see ''Async JavaScript''."},{"prompt":"In a component-based UI, ''state'' refers to…","options":["the CSS file","data that changes and drives what renders","the server","the HTML doctype"],"answer":1,"explanation":"State is the changing data a component renders from — see ''Components and state''."},{"prompt":"Which keeps the page from reloading when a form is submitted?","options":["event.stopPropagation()","event.preventDefault()","return true","form.reset()"],"answer":1,"explanation":"preventDefault cancels the browser''s default submit — see ''Forms and validation''."},{"prompt":"Which attribute improves accessibility for screen readers on an icon-only button?","options":["title","aria-label","class","data-id"],"answer":1,"explanation":"aria-label supplies an accessible name — see ''Forms, validation, and accessible UI''."},{"prompt":"What does `async/await` help you avoid?","options":["deeply nested .then() callbacks","using const","writing HTML","CSS media queries"],"answer":0,"explanation":"await lets you write asynchronous code that reads top-to-bottom — see ''Async JavaScript''."}]}'::jsonb, null, 10),
  (2, 'Modern JavaScript: ES6+ you use every day', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Declare variables safely with const and let, write arrow functions, transform data with array methods, and split code into modules. Warm-up: from the diagnostic, which of const or let can be reassigned?"},{"heading":"The idea","text":"Modern JavaScript (ES2015 and later, often called ES6+) replaced old habits with clearer tools. Prefer `const` for values you will not reassign and `let` for those you will; avoid `var`, which leaks out of blocks. Arrow functions give a short syntax for small functions. Array methods like `map`, `filter`, and `reduce` transform data without manual loops. Modules let one file share code with another using `export` and `import`.\n\n```js\nconst prices = [10, 25, 4, 60];\nconst withTax = prices.map((p) => p * 1.2);\nconst affordable = prices.filter((p) => p < 30);\nexport const CURRENCY = ''USD'';\n```"},{"heading":"Worked example","text":"Trace what each line produces:\n\n```js\nconst nums = [3, 8, 1, 9];\nconst doubled = nums.map((n) => n * 2); // [6, 16, 2, 18]\nconst big = nums.filter((n) => n > 5);  // [8, 9]\nconst total = nums.reduce((sum, n) => sum + n, 0); // 21\nconsole.log(doubled, big, total);\n// [6, 16, 2, 18] [8, 9] 21\n```\n\n`map` keeps the same length; `filter` may shrink it; `reduce` collapses the array to a single value, starting from the seed `0`."},{"heading":"Your turn","text":"Predict each result. (1) `[''a'', ''bb'', ''ccc''].map((s) => s.length)`. (2) `[5, 12, 7, 30].filter((n) => n >= 10)`. (3) `[1, 2, 3, 4].reduce((a, b) => a + b, 0)`. (4) With `const user = { name: ''Ada'' };`, does `user.name = ''Grace''` throw? Answers: (1) `[1, 2, 3]`; (2) `[12, 30]`; (3) `10`; (4) no — const blocks reassigning the binding, but the object''s properties can still change."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking `const` makes an object immutable — it only stops reassignment of the variable itself. Mistake: reaching for `var` out of habit; its function scope causes surprising bugs. Exit: (a) Which method returns a single accumulated value? (b) Which keyword should you default to? Answers: reduce; const."}]}'::jsonb, 'const first; use let only when you must reassign; never var.', 13),
  (3, 'The DOM and events, deeper', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Select elements, change their content and classes, and respond to user events including clicks and typing. Warm-up: which method registers an event handler?"},{"heading":"The idea","text":"The DOM (Document Object Model) is the browser''s live, tree-shaped representation of your HTML. JavaScript reads and edits that tree. Use `document.querySelector` to grab an element, `textContent` or `classList` to change it, and `addEventListener` to react to events. The handler receives an `event` object describing what happened.\n\n```html\n<button id=\"like\">Like</button>\n<span id=\"count\">0</span>\n```\n\n```js\nconst button = document.querySelector(''#like'');\nconst count = document.querySelector(''#count'');\nlet likes = 0;\nbutton.addEventListener(''click'', () => {\n  likes += 1;\n  count.textContent = likes;\n});\n```"},{"heading":"Worked example","text":"Trace this input handler as the user types ''hi'':\n\n```js\nconst field = document.querySelector(''#name'');\nconst echo = document.querySelector(''#echo'');\nfield.addEventListener(''input'', (event) => {\n  echo.textContent = event.target.value.toUpperCase();\n});\n// user types ''h'' -> echo shows ''H''\n// user types ''i'' -> echo shows ''HI''\n```\n\n`event.target` is the element that fired the event; `.value` is its current text. The handler runs on every keystroke, so the echo updates live."},{"heading":"Your turn","text":"Given the counter code above: (1) After three clicks, what is `count.textContent`? (2) What does `event.target` refer to inside a click handler on `#like`? (3) Which method finds the first element matching a CSS selector? (4) True or false: `classList.toggle(''active'')` adds the class if absent and removes it if present. Answers: (1) `''3''` (text, not the number 3); (2) the button element with id `like`; (3) `document.querySelector`; (4) true."},{"heading":"Common mistakes & exit ticket","text":"Mistake: running DOM code before the element exists — put scripts at the end of the body or use `defer`. Mistake: using `innerHTML` with untrusted user text, which invites injection; prefer `textContent`. Exit: (a) What property safely sets plain text? (b) What does an event handler receive as its argument? Answers: textContent; an event object."}]}'::jsonb, 'Select, then listen: querySelector to find, addEventListener to react.', 13),
  (4, 'Async JavaScript: promises, fetch, and APIs', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why the browser is asynchronous, read and write promises, and load data from an API with fetch and async/await. Warm-up: what type of value does fetch return?"},{"heading":"The idea","text":"The browser cannot freeze while waiting for a network reply, so slow work is *asynchronous*: it finishes later. A `Promise` represents a value that is not ready yet. `fetch` returns a promise for an HTTP response. The `async`/`await` syntax lets you write asynchronous steps that read top to bottom, and `try`/`catch` handles failures.\n\n```js\nasync function loadUser(id) {\n  const response = await fetch(`https://api.example.com/users/${id}`);\n  if (!response.ok) throw new Error(''Request failed'');\n  const user = await response.json();\n  return user;\n}\n```"},{"heading":"Worked example","text":"Trace the order of the logs:\n\n```js\nconsole.log(''A'');\nasync function run() {\n  console.log(''B'');\n  const res = await fetch(''/data.json''); // pauses here\n  const data = await res.json();\n  console.log(''C'', data.length);\n}\nrun();\nconsole.log(''D'');\n// Output order: A, B, D, then later C <count>\n```\n\n''A'' and ''B'' run immediately, then `await` yields control so ''D'' prints before the network finishes. ''C'' prints last, once the response arrives and is parsed."},{"heading":"Your turn","text":"(1) What does `await response.json()` produce — a promise or the parsed data? (2) Where do you put code that should run only if the fetch fails? (3) Can you use `await` at the top level of a normal function that is not marked `async`? (4) In the worked example, why does ''D'' print before ''C''? Answers: (1) the parsed data, because await unwraps the promise; (2) in a `catch` block; (3) no — `await` requires an `async` function (or a module top level); (4) because `await` pauses `run` and lets the rest of the script continue."},{"heading":"Common mistakes & exit ticket","text":"Mistake: forgetting that `fetch` does not reject on HTTP errors like 404 — you must check `response.ok` yourself. Mistake: leaving out `await`, so you handle a pending promise instead of its value. Exit: (a) Which property tells you the request succeeded at the HTTP level? (b) What keyword unwraps a promise''s value? Answers: response.ok; await."}]}'::jsonb, 'await pauses inside an async function until a promise settles.', 14),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"`[''x'', ''yy''].map((s) => s.length)` evaluates to…","options":["[''x'', ''yy'']","[1, 2]","3","2"],"answer":1,"explanation":"map returns each string''s length."},{"prompt":"Which safely sets plain text without HTML-injection risk?","options":["innerHTML","textContent","outerHTML","insertAdjacentHTML"],"answer":1,"explanation":"textContent treats the value as literal text."},{"prompt":"Inside `button.addEventListener(''click'', (e) => {...})`, `e.target` is…","options":["the document","the clicked button","the window","a Promise"],"answer":1,"explanation":"target is the element that fired the event."},{"prompt":"`fetch()` rejects its promise when…","options":["the server returns 404","the server returns 500","the network request cannot be made at all","the JSON is empty"],"answer":2,"explanation":"HTTP error statuses still resolve; check response.ok yourself."},{"prompt":"`await` can be used…","options":["anywhere","only inside an async function or a module top level","only inside a loop","only with const"],"answer":1,"explanation":"await requires an async context."},{"prompt":"Which reduces `[2, 4, 6]` to its sum `12`?","options":[".map((n) => n)",".filter((n) => n)",".reduce((a, b) => a + b, 0)",".forEach((n) => n)"],"answer":2,"explanation":"reduce accumulates into one value."}]}'::jsonb, null, 8),
  (6, 'Components and state: thinking in reusable pieces', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what a component is, distinguish props from state, and describe how changing state updates the view. Warm-up: in a UI, what does ''state'' mean?"},{"heading":"The idea","text":"Modern interfaces are built from *components*: small, reusable pieces that own a slice of the UI. A component receives inputs (often called *props*) and holds *state* — the data that changes over time. The core idea, shared by React-style libraries, is that the view is a function of state: when state changes, the framework re-renders the affected piece for you, so you describe *what* the UI should look like rather than manually poking the DOM.\n\n```js\nfunction Counter({ label }) {\n  let count = 0; // conceptual state\n  function increment() {\n    count += 1;\n    render();\n  }\n  function render() {\n    return `${label}: ${count}`;\n  }\n  return { increment, render };\n}\n```"},{"heading":"Worked example","text":"Trace a state update in a React-style mental model:\n\n```js\n// state: { count: 0 }\n// view renders: ''Count: 0''\n// user clicks +, handler calls setCount(count + 1)\n// state becomes: { count: 1 }\n// framework re-renders view: ''Count: 1''\n```\n\nYou never edit the text node by hand. You update state (`setCount`) and the library recomputes the view. Props flow *down* from parent to child; state is *local* to the component that owns it."},{"heading":"Your turn","text":"(1) Which is passed in from a parent — props or state? (2) Which does a component own and change over time? (3) In ''the view is a function of state'', what triggers a re-render? (4) True or false: with a component model you usually call `document.querySelector` to update text. Answers: (1) props; (2) state; (3) a change to state; (4) false — you change state and let the library render."},{"heading":"Common mistakes & exit ticket","text":"Mistake: mutating state directly and expecting the view to update — use the provided setter so the framework knows to re-render. Mistake: confusing props (inputs from outside) with state (internal, changing data). Exit: (a) Props flow in which direction? (b) The view is a function of what? Answers: down, from parent to child; state."}]}'::jsonb, 'UI is a function of state: change the state, and the view re-renders.', 13),
  (7, 'Forms, validation, and accessible responsive UI', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Handle form submission in JavaScript, validate input, and make interfaces accessible and responsive. Warm-up: which method stops a form from reloading the page?"},{"heading":"The idea","text":"A form submit normally reloads the page. Call `event.preventDefault()` to handle it yourself, read values, and *validate* them before use. Accessibility means everyone can use the UI: pair every input with a `<label>`, give icon-only controls an `aria-label`, and keep it keyboard-navigable. *Responsive* design adapts to screen size, often with CSS media queries.\n\n```html\n<form id=\"signup\">\n  <label for=\"email\">Email</label>\n  <input id=\"email\" type=\"email\" required />\n  <button type=\"submit\">Join</button>\n</form>\n```\n\n```js\nconst form = document.querySelector(''#signup'');\nform.addEventListener(''submit'', (event) => {\n  event.preventDefault();\n  const email = form.email.value.trim();\n  if (!email.includes(''@'')) {\n    alert(''Please enter a valid email'');\n    return;\n  }\n  console.log(''Submitting'', email);\n});\n```"},{"heading":"Worked example","text":"Trace validation for two inputs:\n\n```js\nfunction validate(email) {\n  if (email.trim() === '''') return ''Email is required'';\n  if (!email.includes(''@'')) return ''Email must contain @'';\n  return ''ok'';\n}\nconsole.log(validate(''   ''));        // ''Email is required''\nconsole.log(validate(''ada''));        // ''Email must contain @''\nconsole.log(validate(''ada@site.io'')); // ''ok''\n```\n\nEach guard clause returns early on the first problem, so the message tells the user exactly what to fix."},{"heading":"Your turn","text":"(1) What does `event.preventDefault()` stop? (2) What connects a `<label>` to its input? (3) `validate(''bob'')` returns what, given the code above? (4) Which attribute gives an icon-only button an accessible name? Answers: (1) the browser''s default form submit and page reload; (2) the label''s `for` attribute matching the input''s `id`; (3) `''Email must contain @''`; (4) `aria-label`."},{"heading":"Common mistakes & exit ticket","text":"Mistake: trusting client-side validation alone — always validate on the server too, since users can bypass the browser. Mistake: placeholder text used *instead* of a label; placeholders vanish on typing and are not reliable labels. Exit: (a) Which method cancels the default submit? (b) What makes a control usable by screen readers when it has no visible text? Answers: preventDefault; an accessible name via label or aria-label."}]}'::jsonb, 'preventDefault stops the reload; labels and aria give everyone access.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"const","translation":"a declaration for a binding that cannot be reassigned","example":"const MAX = 100; reassigning MAX throws an error."},{"term":"arrow function","translation":"a short function syntax written with =>","example":"const double = (n) => n * 2;"},{"term":"the DOM","translation":"the browser''s live tree of objects representing the page''s HTML","example":"querySelector reads a node from the DOM."},{"term":"Promise","translation":"an object representing a value that will be ready later","example":"fetch returns a Promise for the response."},{"term":"state","translation":"the changing data a component renders from","example":"Updating state re-renders the view."},{"term":"accessibility","translation":"designing UI so everyone, including assistive-tech users, can use it","example":"An aria-label gives an icon button an accessible name."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"In a component model, props are…","options":["internal changing data","inputs passed in from a parent","CSS rules","network requests"],"answer":1,"explanation":"Props flow down from a parent."},{"prompt":"''The view is a function of state'' means a re-render is triggered by…","options":["editing the DOM by hand","a change to state","a page reload","a CSS media query"],"answer":1,"explanation":"Change state, and the library re-renders."},{"prompt":"`event.preventDefault()` in a submit handler…","options":["clears the form","stops the default page reload","validates the email","focuses the input"],"answer":1,"explanation":"It cancels the browser''s default submit."},{"prompt":"A `<label for=\"email\">` connects to an input by matching its…","options":["class","name","id","type"],"answer":2,"explanation":"The for attribute matches the input''s id."},{"prompt":"Why validate on the server as well as the client?","options":["servers are faster","clients can bypass browser checks","CSS requires it","to avoid using const"],"answer":1,"explanation":"Client-side checks can be bypassed."},{"prompt":"Which gives an icon-only button an accessible name?","options":["placeholder","aria-label","value","data-name"],"answer":1,"explanation":"aria-label supplies the accessible name."}]}'::jsonb, null, 8),
  (10, 'Applied project: build an interactive widget', 'writing', '{"sections":[{"heading":"The task","text":"Build one small, interactive widget with plain modern JavaScript: either a to-do list (add items, mark them done, remove them) or a weather widget (enter a city, fetch and display current conditions from a public weather API). Keep it to a single HTML file plus a script."},{"heading":"Milestones","text":"1) Sketch the state: for the to-do, an array of `{ text, done }`; for weather, the last fetched result. 2) Wire up events with `addEventListener` and stop default form submits with `event.preventDefault()`. 3) For weather, load data with `fetch` inside an `async` function and handle failures in a `catch`. 4) Render from state each time it changes, using `textContent` for user-supplied text. 5) Make it accessible: label every input and give icon buttons an `aria-label`."},{"heading":"Self-check rubric","text":"✔ State is stored in a variable, not scattered in the DOM. ✔ Events use addEventListener and preventDefault where a form is involved. ✔ Any network call uses async/await with error handling and checks response.ok. ✔ User text is inserted with textContent, not innerHTML. ✔ Inputs have labels and interactive controls are keyboard-usable. If all five hold, your widget is modern, safe, and accessible."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0002-0000-4000-8000-000000000009' and l.position = v.pos
);
